import React from 'react';
import { useState} from 'react';

import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';

import List from '@mui/material/List';
import Divider from '@mui/material/Divider';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import InboxIcon from '@mui/icons-material/MoveToInbox';
import MailIcon from '@mui/icons-material/Mail';

import { NavLink } from 'react-router-dom'
import ArticleIcon from '@mui/icons-material/Article';
import AutoStoriesIcon from '@mui/icons-material/AutoStories';

export default function HomeHeaderNavi(){

    // ハンバーガーメニューの開閉
    const [isOpen, setIsOpen] = useState(false);

    const toggleMenu = () => setIsOpen(!isOpen);


    return(
        <>
        {/*ヘッダー*/}
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static"  sx={{background:'white'}}>
                <Toolbar>
                    {/* ハンバーガーアイコン */}
                    <IconButton
                            size="large"
                            edge="start"
                            aria-label="menu"
                            onClick={toggleMenu}
                            >
                        <MenuIcon />
                    </IconButton >
                    {/* タイトル */}
                    <Typography variant="h6" component="div" sx={{ flexGrow: 1, color:'black', textAlign:'left', paddingLeft:2}}>
                    データ分析
                    </Typography>
                </Toolbar>
                </AppBar>
            </Box>
            {/*ヘッダー終わり*/}

            {/* ハンバーガーメニューの表示 */}
                <div>
                    {isOpen && (
                        <Box sx={{ width: 250 }} role="presentation" onClick={toggleMenu}>
                            <NavLink to="/omocomi/newbook">
                                <ListItemButton>
                                    <ListItemIcon>
                                    <AutoStoriesIcon />
                                    </ListItemIcon>
                                    <ListItemText primary="新刊情報" sx={{color:'black'}}></ListItemText>
                                </ListItemButton>
                            </NavLink>
                            <NavLink to="/omocomi/news">
                                <ListItemButton>
                                    <ListItemIcon>
                                    <ArticleIcon />
                                    </ListItemIcon>
                                    <ListItemText primary="News" sx={{color:'black'}} />
                                </ListItemButton>
                            </NavLink>
                            <Divider />
                        </Box>
                    )}
                </div>
                {/* ハンバーガーメニューの表示の終わり */}
        </>
    );
};

